function init(){defaults({target:4,notes:[]});state.date=today()}init();
let chosenDate=today();
function habitEditor(id){const h=state.habits.find(x=>x.id===id);editModal(h?'调整小习惯':'种下一个小习惯',field('一个做得到的小行动','name','text',h?.name||'','required maxlength="40" placeholder="例如：晚饭后散步十分钟"')+field('什么时候想起它','reminder','text',h?.reminder||'','required maxlength="60" placeholder="例如：收好餐桌以后"'),v=>{if(state.habits.some(x=>x.id!==id&&x.name===v.name)){toast('这个习惯已经有啦');return false}if(h)Object.assign(h,v);else state.habits.push({...v,id:uid(),icon:'🌱'});commit('小习惯已经种下')});if(h){$('#edit-form').insertAdjacentHTML('beforeend',btn('移除这个习惯','remove','danger'));on('remove',()=>{state.habits=state.habits.filter(x=>x.id!==id);for(const d of Object.keys(state.logs))state.logs[d]=state.logs[d].filter(x=>x!==id);closeModal();commit('已移除，可撤销')})}}
function render(){nav();const checked=state.logs[chosenDate]||[],count=state.habits.filter(h=>checked.includes(h.id)).length;
if(active===0){$('#app').innerHTML=`<div class="two-col"><div>${hero(chosenDate===today()?'今天的小小成长':chosenDate,`${count}<small>/ ${state.habits.length} 个小行动</small>`,count&&count===state.habits.length?'今天的小行动都完成啦。':'不用一下做很多，选一个现在能做到的。','plant')}${heading('照顾好自己',btn('＋ 小习惯','add',''))}<div class="list">${list(state.habits,h=>`<article class="list-item"><span class="tile-icon">${icon('leaf')}</span><div class="content"><strong>${esc(h.name)}</strong><p>${esc(h.reminder)}</p></div>${check('check',h.id,checked.includes(h.id),(checked.includes(h.id)?'撤销打卡':'打卡')+h.name)}</article>`)}</div></div><aside class="stack"><section class="card"><h3>最近 7 天的足迹</h3><div class="week-grid" style="margin-top:20px">${Array.from({length:7},(_,i)=>{const d=daysAgo(6-i),n=(state.logs[d]||[]).length;return `<div class="day-cell ${n?'hit':''} ${d===today()?'current':''}"><span>${['日','一','二','三','四','五','六'][new Date(d+'T12:00:00').getDay()]}</span><b>${n?'✓':d.slice(-2)}</b></div>`}).join('')}</div><p class="hint" style="margin-top:16px">漏一天也没关系，随时可以继续。</p></section><label>查看或补记日期<input id="habit-date" type="date" value="${chosenDate}" max="${today()}"></label></aside></div>`;actions('check',id=>{const logs=state.logs[chosenDate]||[];state.logs[chosenDate]=logs.includes(id)?logs.filter(x=>x!==id):[...logs,id];commit(logs.includes(id)?'已撤销打卡':'为这个小行动，给自己一点鼓励')});on('add',()=>habitEditor());$('#habit-date').onchange=e=>{if(e.target.value&&e.target.value<=today()){chosenDate=e.target.value;render()}else toast('只能记录今天或之前的日期')}}
if(active===1){$('#app').innerHTML=`<div class="screen-body">${heading('每个小行动，都算数')}<div class="notice">最近 7 天目标：每个习惯完成 ${p.target} 次。没有断签惩罚。</div>${state.habits.map(h=>{const n=Array.from({length:7},(_,i)=>(state.logs[daysAgo(i)]||[]).includes(h.id)).filter(Boolean).length;return `<section class="card" style="margin-top:16px"><div class="between"><h3>${esc(h.name)}</h3><span>${n} / ${p.target}</span></div>${progress(n/p.target*100)}<p class="hint">${n>=p.target?'已达到自己的目标。':`已经积累 ${n} 次行动，慢慢来。`}</p></section>`}).join('')}<form id="target-form" class="stack" style="margin-top:24px">${field('给自己定一个 7 天目标','target','number',p.target,'required min="1" max="7"')}<button class="secondary">保存目标</button></form></div>`;form('target-form',v=>{p.target=+v.target;commit()})}
if(active===2){$('#app').innerHTML=`<div class="screen-body">${heading('我的小习惯',btn('＋ 添加','add',''))}<div class="list">${list(state.habits,h=>`<div class="list-item"><div class="content"><strong>${esc(h.name)}</strong><p>${esc(h.reminder)}</p></div><button data-edit="${h.id}">修改</button></div>`)}</div><p class="subtle" style="margin-top:22px">把目标写成具体的小行动，比如“收好书包”，比“我要更自律”更容易开始。提醒线索只显示在页面，不会发送通知。</p></div>`;on('add',()=>habitEditor());actions('edit',habitEditor)}}
shell([['今天','leaf'],['足迹','graph'],['习惯','list']]);render();
